import { Router, json, type ErrorRequestHandler } from 'express';
import { z } from 'zod';
import { BrowserSessions } from '../../library/BrowserSessions';
import { validateAccessToken } from '../../services/AuthService';
import { AuthorizationChanged } from '../../storage/library/BrowserAuthorizationRecords';
import { authenticateLibrary, isLocalBrowserRequest } from './middleware';
import { parseInstallRef } from '../../utils/installRef';
import type { TelemetryService } from '../../services/TelemetryService';
import type {
  BrowserSessionResponse,
  ErrorResponse,
} from '../../types/api-responses';

const tokenBody = z.object({ token: z.string().min(1) });
const launchBody = z.object({ code: z.string().min(1) });
const signInBody = z.object({
  token: z.string().min(1),
  refreshToken: z.string().optional(),
  installRef: z.string().optional(),
});

export const createBrowserAccessRouter = ({
  token,
  sessions,
  telemetry,
}: {
  token: string;
  sessions: BrowserSessions;
  telemetry?: Pick<TelemetryService, 'reportInstallRefActivations'>;
}): Router => {
  const router = Router();
  router.post('/browser-sessions', json({ limit: '8kb' }), async (req, res) => {
    if (!isLocalBrowserRequest(req)) return res.sendStatus(403);
    const parsed = signInBody.safeParse(req.body);
    if (!parsed.success) return res.sendStatus(400);
    const generation = sessions.beginSignIn();
    let profile: Awaited<ReturnType<typeof validateAccessToken>>;
    try {
      profile = await validateAccessToken(
        sessions.config.getProxyUrl(),
        parsed.data.token,
      );
    } catch {
      return res.status(502).json({
        error: 'Could not verify Google sign-in',
      } satisfies ErrorResponse);
    }
    if (!profile) return res.sendStatus(401);
    const browserToken = sessions.completeSignIn({
      ...parsed.data,
      generation,
      email: profile.email,
      userId: profile.userId,
    });
    const carriedInstallRef = parseInstallRef(parsed.data.installRef);
    if (carriedInstallRef) {
      sessions.config.completeInstallRefSignIn(
        carriedInstallRef,
        profile.userId,
      );
    }
    telemetry?.reportInstallRefActivations();
    return res.json({ token: browserToken } satisfies BrowserSessionResponse);
  });
  router.post(
    '/browser-sessions/exchange',
    json({ limit: '8kb' }),
    (req, res) => {
      if (!isLocalBrowserRequest(req)) return res.sendStatus(403);
      const parsed = launchBody.safeParse(req.body);
      if (!parsed.success) return res.sendStatus(400);
      const browserToken = sessions.exchange(parsed.data.code);
      return browserToken
        ? res.json({ token: browserToken } satisfies BrowserSessionResponse)
        : res.sendStatus(401);
    },
  );
  router.post('/launch-codes', authenticateLibrary(token), (_req, res) =>
    res.json({ code: sessions.createLaunchCode() }),
  );
  router.post(
    '/browser-sessions/revoke',
    authenticateLibrary(token, sessions),
    (req, res) => {
      const parsed = tokenBody.safeParse({
        token: req.headers.authorization?.slice('Bearer '.length),
      });
      if (!parsed.success) return res.sendStatus(400);
      sessions.revoke(parsed.data.token);
      return res.json({ success: true });
    },
  );
  const handleError: ErrorRequestHandler = (error, _req, res, _next) => {
    if (error instanceof AuthorizationChanged)
      return res
        .status(409)
        .json({ error: error.message } satisfies ErrorResponse);
    res.status(503).json({
      error:
        'Browser authorization is unavailable. Please retry or sign in again.',
    } satisfies ErrorResponse);
  };
  router.use(handleError);
  return router;
};
